import eslint from '@eslint/js';
import prettier from 'eslint-config-prettier';
import tseslint from 'typescript-eslint';

/**
 * API lint rules.
 *
 * Type-aware linting is on, which is what makes the floating-promise and
 * unsafe-argument rules worth having in a service that is almost entirely
 * asynchronous.
 */
export default tseslint.config(
  {
    ignores: [
      'dist/**',
      'coverage/**',
      'node_modules/**',
      // Generated by Prisma and already carries @ts-nocheck.
      'src/generated/**',
      'prisma/migrations/**',
      '*.config.mjs',
      // Loaded by the Prisma CLI, which brings its own types.
      'prisma.config.ts',
    ],
  },

  eslint.configs.recommended,
  ...tseslint.configs.recommendedTypeChecked,
  ...tseslint.configs.stylisticTypeChecked,

  {
    languageOptions: {
      parserOptions: {
        // A dedicated project: the build tsconfig excludes tests, scripts and
        // config files, which type-aware linting still needs to see.
        project: ['./tsconfig.eslint.json'],
        tsconfigRootDir: import.meta.dirname,
      },
    },
    rules: {
      // NestJS DI relies on parameter properties and decorator metadata.
      '@typescript-eslint/no-extraneous-class': 'off',
      '@typescript-eslint/parameter-properties': 'off',

      // An unhandled rejection in a request handler is a silent 500.
      '@typescript-eslint/no-floating-promises': 'error',
      '@typescript-eslint/no-misused-promises': 'error',

      // `any` defeats the point of the shared contract package.
      '@typescript-eslint/no-explicit-any': 'error',
      '@typescript-eslint/no-unsafe-assignment': 'warn',
      '@typescript-eslint/no-unsafe-member-access': 'warn',
      '@typescript-eslint/no-unsafe-call': 'warn',
      '@typescript-eslint/no-unsafe-return': 'warn',
      '@typescript-eslint/no-unsafe-argument': 'warn',

      /**
       * `||` is deliberate for string configuration values: an empty
       * environment variable and an unset one both mean "not configured", and
       * `??` would let `''` through as a real value. The rule stays on for
       * every other type, where `||` really is a bug waiting to happen.
       */
      '@typescript-eslint/prefer-nullish-coalescing': [
        'error',
        { ignorePrimitives: { string: true } },
      ],

      '@typescript-eslint/consistent-type-imports': [
        'error',
        { prefer: 'type-imports', fixStyle: 'inline-type-imports' },
      ],
      '@typescript-eslint/no-unused-vars': [
        'error',
        { argsIgnorePattern: '^_', varsIgnorePattern: '^_', caughtErrors: 'none' },
      ],

      // `console` is for the bootstrap failure path only; everything else uses
      // the structured logger.
      'no-console': ['warn', { allow: ['error'] }],
      eqeqeq: ['error', 'smart'],
      'prefer-const': 'error',
      'no-param-reassign': 'error',
    },
  },

  {
    /**
     * The Vercel entry point is plain JavaScript on purpose — see the comment
     * in the file — so it sits outside the TypeScript project and cannot be
     * type-aware linted. The ordinary JavaScript rules still apply.
     */
    files: ['api/**/*.js'],
    languageOptions: {
      // Not part of the TypeScript project, so type-aware rules cannot run
      // here; turning the project off is what stops the parser erroring.
      parserOptions: { project: false, program: null },
      globals: { console: 'readonly' },
    },
    rules: {
      ...tseslint.configs.disableTypeChecked.rules,
      // The bootstrap failure path logs; the structured logger is not up yet.
      'no-console': 'off',
    },
  },

  {
    /**
     * Provider and driver stubs implement an async interface by throwing. That
     * is the point — an unimplemented integration must fail closed rather than
     * return a plausible result — so `require-await` is relaxed for exactly
     * those files rather than switched off everywhere.
     */
    files: [
      'src/modules/payments/providers/*.ts',
      'src/storage/s3.driver.ts',
      'src/mail/console.transport.ts',
      // Overrides an async base-class method whose signature we cannot change.
      'src/common/guards/scoped-throttler.guard.ts',
    ],
    rules: { '@typescript-eslint/require-await': 'off' },
  },

  {
    // Tests and scripts legitimately use console and loose typing.
    files: ['test/**/*.ts', 'prisma/**/*.ts', 'scripts/**/*.ts'],
    rules: {
      'no-console': 'off',
      '@typescript-eslint/require-await': 'off',
      '@typescript-eslint/prefer-nullish-coalescing': 'off',
      '@typescript-eslint/no-unsafe-assignment': 'off',
      '@typescript-eslint/no-unsafe-member-access': 'off',
      '@typescript-eslint/no-unsafe-call': 'off',
      '@typescript-eslint/no-unsafe-argument': 'off',
      '@typescript-eslint/no-non-null-assertion': 'off',
    },
  },

  prettier,
);
